        return "lezing_geen_object"
    sleutels = set(item)
    if sleutels - _VERPLICHTE_LEZINGSSLEUTELS:
        return "lezing_onbekende_sleutel"
    waarden: dict[str, str] = {}
    for sleutel in ("lezing", "bron", "grond"):
        tekst = _niet_lege_tekst(item.get(sleutel))
