definitie, maar één melding::

    VERDUIDELIJKING NODIG: {"vraag": "...", "lezingen": [
        {"lezing": "...", "bron": "bron 2", "grond": "..."},
        {"lezing": "...", "bron": "context: DJI", "grond": "..."}]}

