def _get_environment_config() -> dict[str, Any]:
    """Bepaal environment en return juiste config."""
    import os

    env = os.getenv("APP_ENV", "production")

    if env == "development":
        return cast(dict[str, Any], ContainerConfigs.development())
    if env == "testing":
        return cast(dict[str, Any], ContainerConfigs.testing())
    return cast(dict[str, Any], ContainerConfigs.production())


class ServiceAdapter:
    """
    Adapter die de nieuwe service architecture wrapped voor compatibility
    met de legacy UnifiedDefinitionGenerator interface.

    Dit maakt het mogelijk om de nieuwe services te gebruiken zonder
    alle UI code meteen aan te passen.
    """

    def __init__(self, container: ServiceContainer):
        """
        Initialiseer adapter met service container.

        Args:
            container: De service container met alle services
        """
        self.container = container
        self.orchestrator = container.orchestrator()
        self.web_lookup = container.web_lookup()
        # UI services worden niet langer vanuit de serviceslaag beheerd

    def get_service_info(self) -> dict:
        """Return service info voor UI detectie."""
        return {
            "service_mode": "container_v2",
            "architecture": "microservices",
            "version": "2.0",
        }

    def _safe_float(self, value: Any, default: float = 0.0) -> float:
        """Safely convert any value to float with fallback.

        Handles None, empty strings, and conversion errors.
        """
        if value is None or value == "":
            return default
        try:
            return float(value)
        except (TypeError, ValueError):
            return default

    def _normalize_severity(self, severity: Any) -> str:
        """Normalize various severity formats to canonical values.

        Maps: error/critical -> high, warning -> medium, other -> low
        """
        # Extract string value from enums or objects
        if hasattr(severity, "value"):
            severity = severity.value
        severity = str(severity).lower() if severity else "low"

        # Map to canonical values
        if severity in ["error", "critical", "high"]:
            return "high"
        if severity in ["warning", "medium"]:
            return "medium"
        return "low"

    def _extract_violations(self, source: Any) -> list[dict]:
        """Extract and normalize violations from dict or object format."""
        violations = []

        # Handle dict format
        if isinstance(source, dict):
            violations = self._extract_dict_violations(source)
        # Handle object format
        elif hasattr(source, "violations") and source.violations:
            violations = self._extract_object_violations(source)

        return violations

    def _extract_dict_violations(self, source: dict) -> list[dict]:
        """Extract violations from dict format."""
        violations = []
        for v in ensure_list(safe_dict_get(source, "violations", [])):
            violations.append(
                {
                    "rule_id": safe_dict_get(
                        v, "rule_id", safe_dict_get(v, "code", "unknown")
                    ),
                    "severity": self._normalize_severity(safe_dict_get(v, "severity")),
                    "description": safe_dict_get(
                        v, "description", safe_dict_get(v, "message", "")
                    ),
                    "suggestion": safe_dict_get(v, "suggestion"),
                }
            )
        return violations

    def _extract_object_violations(self, source: Any) -> list[dict]:
        """Extract violations from object format."""
        violations = []
        for v in source.violations:
            violations.append(
                {
                    "rule_id": getattr(v, "rule_id", "unknown"),
                    "severity": self._normalize_severity(getattr(v, "severity", None)),
                    "description": getattr(v, "description", ""),
                    "suggestion": getattr(v, "suggestion", None),
                }
            )
        return violations

    def _score_of_none(self, waarde: Any) -> float | None:
        """Een expliciete None is 'niet beschikbaar' en blijft None (DEF-622/624)."""
        return None if waarde is None else self._safe_float(waarde)

    def _extract_score(self, result: Any) -> float | None:
        """Extract score from various result formats with safe fallback.

        Een werkelijk aanwezige None (legacy `score` of `overall_score`) blijft
        None; alleen een ontbrekende score valt terug op 0.0.
        """
        # Try modern 'score' field first
        if hasattr(result, "score"):
            return self._score_of_none(result.score)
        # Try dict access
        if isinstance(result, dict) and "score" in result:
            return self._score_of_none(result["score"])
        # Fallback to deprecated key 'overall_score' (dict format only)
        if isinstance(result, dict) and "overall_score" in result:
            return self._score_of_none(result["overall_score"])
        # As a last resort, attempt to convert known result objects to dict-like structures
        for method_name in ("to_dict", "dict", "model_dump"):
            try:
                method = getattr(result, method_name, None)
                if callable(method):
                    data = method()
                    if isinstance(data, dict):
                        if "score" in data:
                            return self._score_of_none(data["score"])
                        if "overall_score" in data:
                            return self._score_of_none(data["overall_score"])
            except Exception as e:
                logger.warning(f"Failed to extract validation score, using 0.0: {e}")
        return 0.0

    def _extract_is_acceptable(self, result: Any, score: float | None) -> bool:
        """Extract acceptance status with fallback to score threshold."""
        # Try direct fields first
        for field in ["is_acceptable", "is_valid"]:
            if hasattr(result, field):
                return bool(getattr(result, field))
            if isinstance(result, dict) and field in result:
                return bool(result[field])
        # Fallback to score threshold. DEF-622: zonder totaalscore (None) is
        # er geen drempel te toetsen — fail-closed niet acceptabel.
        return score is not None and score >= 0.5

    @staticmethod
    def _met_discriminator(genormaliseerd: dict, bron: Any) -> dict:
        """Neem de contractvelden mee en maak de runstatus expliciet (DEF-621/624).

        `normalize_validation` bouwt bewust een nieuw dict met vaste sleutels
        - dat maakt de vorm voorspelbaar, maar wierp ook het verschil weg
        tussen een oordeel en een fail-closed placeholder. De Generator-tab
        rendert precies dit genormaliseerde dict, dus zonder deze velden kan
        de gedeelde stop daar niet vuren en verschijnt "Overall Score: 0.00"
        alsof de definitie slecht scoort.

        Wat de bron werkelijk draagt wordt doorgegeven. DEF-624 keert de
        oude keuze om legacy "niets op te dringen" om: een resultaat zónder
        geldige `validation_status` is geen uitgevoerde run en wordt expliciet
        `validation_unknown` met reden contract_status_missing/invalid
        (`services.validation.result_contract`). Een hoge score of
        `is_acceptable=True` zonder runbewijs kwam anders als groen oordeel
        de UI in (probe /tmp/def624-status-loss-probe.log). Er wordt geen
        `validated` verzonnen en geen readiness verzonnen.

        Leest zowel expliciete dictsleutels als werkelijk aanwezige
        objectattributen, want niet elk pad door `normalize_validation`
        levert een dict aan. Op de objectkant geldt een typecontrole: een
        `Mock` verzint elk attribuut dat je opvraagt, en een kale `hasattr`
        zou daar velden uit het niets toekennen.
        """
        from services.validation.result_contract import (  # lazy, zoals mappers
            lees_veld,
            met_expliciete_runstatus,
            neem_contractvelden_over,
        )

        # DEF-622: de gestructureerde regeluitkomsten en de gate reizen mee.
        # `rule_results` draagt de CON-01-deeluitkomsten (aanleiding, reden,
        # vervolgstap) die de UI moet tonen nu er geen totaalscore is; zonder
        # dit transport verdwenen ze op precies dit pad. DEF-743/624: ook de
        # bronbeoordeling (`source_assessment`) hoort bij het resultaat.
        if isinstance(bron, dict):
            # Een dict is al de transportvorm: alles wat er staat reist mee.
            for veld in (
                "validation_status",
                "unknown_reason",
                "validation_readiness",
                "rule_results",
                "rule_statuses",
                "review_required",
                "evaluation_coverage",
                "detailed_scores",
                "acceptance_gate",
                "source_assessment",
            ):
                if veld in bron:
                    genormaliseerd[veld] = bron[veld]
        else:
            # Objectkant: alleen werkelijk gedragen attributen (geen
            # Mock-verzinsels), met aanwezigheid vóór typecontrole zodat een
            # ongeldige status "ongeldig" blijft en een expliciete lege
            # bronbeoordeling (None) niet verdwijnt (reviewbevindingen 4/5).
            neem_contractvelden_over(genormaliseerd, bron)
            aanwezig, scores = lees_veld(bron, "detailed_scores")
            if aanwezig and isinstance(scores, dict):
                genormaliseerd["detailed_scores"] = scores
        return met_expliciete_runstatus(genormaliseerd)

    def _score_of_niet_beschikbaar(self, bron: Any) -> float | None:
        """`overall_score` (of legacy `score`) uit een dict: None blijft None.

        Een expliciete None betekent 'totaalscore niet beschikbaar' en mag
        nooit als 0.0 doorreizen — dat is de impliciete nul die B-06 verbiedt
        (DEF-622). Dat geldt ook voor de legacy-sleutel `score` (DEF-624,
        reviewbevinding 1): anders werd 'niet beschikbaar' via to_ui_response
        alsnog een opslaanbare nul. Ontbreekt elke scoresleutel, dan blijft
        de oude default 0.0.
        """
        if isinstance(bron, dict):
            if "overall_score" in bron:
                return self._score_of_none(bron["overall_score"])
            if "score" in bron:
                return self._score_of_none(bron["score"])
        return self._safe_float(safe_dict_get(bron, "score", 0.0))

    def normalize_validation(self, result: Any) -> dict:
        """Normalize any validation format to canonical V2 dict.

        Maps various validation formats to the canonical ValidationDetailsDict:
        - Schema-conform TypedDict via ensure_schema_compliance
        - Legacy ValidationResult dataclass/object via adapter
        - Ensures severity mapping (error->high, warning->medium, other->low) for legacy items
        """
        # Handle None case. DEF-624: geen resultaat is geen run; de UI krijgt
        # dat expliciet te zien in plaats van een stille 0.0.
        if result is None:
            return self._met_discriminator(
                {
                    "overall_score": 0.0,
                    "is_acceptable": False,
                    "violations": [],
                    "passed_rules": [],
                },
                {},
            )

        # If it's already a dict-like result, normalize directly
        if isinstance(result, dict):
            return self._met_discriminator(
                {
                    "overall_score": self._score_of_niet_beschikbaar(result),
                    "is_acceptable": bool(
                        safe_dict_get(
                            result,
                            "is_acceptable",
                            safe_dict_get(result, "is_valid", False),
                        )
                    ),
                    "violations": ensure_list(safe_dict_get(result, "violations", [])),
                    "passed_rules": ensure_list(
                        safe_dict_get(result, "passed_rules", [])
                    ),
                },
                result,
            )

        # Try common object->dict converters first (supports Mock().to_dict())
        for method_name in ("to_dict", "dict", "model_dump"):
            conv = getattr(result, method_name, None)
            if callable(conv):
                try:
                    data = conv()
                    if isinstance(data, dict):
                        return self._met_discriminator(
                            {
                                "overall_score": self._score_of_niet_beschikbaar(data),
                                "is_acceptable": bool(
                                    safe_dict_get(
                                        data,
                                        "is_acceptable",
                                        safe_dict_get(data, "is_valid", False),
                                    )
                                ),
                                "violations": ensure_list(
                                    safe_dict_get(data, "violations", [])
                                ),
                                "passed_rules": ensure_list(
                                    safe_dict_get(data, "passed_rules", [])
                                ),
                            },
                            data,
                        )
                except (TypeError, ValueError, AttributeError) as e:
                    # DEF-229: Log failed dict conversion attempts for debugging
                    logger.debug(f"Dict conversion method {method_name} failed: {e}")

        # Prefer schema-compliant adapter for dataclass/TypedDict
        try:
            from services.validation.mappers import (
                ensure_schema_compliance,  # lazy import
            )

            schema = ensure_schema_compliance(result)
            # Derive score robustly: prefer schema value, otherwise fallback extract
            overall = (
                self._score_of_niet_beschikbaar(schema)
                if "overall_score" in schema
                else self._extract_score(result)
            )

            # Derive acceptance robustly: prefer schema, else based on score
            is_acceptable = schema.get("is_acceptable")
            if is_acceptable is None:
                is_acceptable = self._extract_is_acceptable(result, overall)

            # DEF-621: bewust uit `result` en niet uit `schema`.
            # `ensure_schema_compliance` bouwt een vers TypedDict met een
            # vaste sleutelset waarin de discriminator niet voorkomt; lezen
            # uit `schema` zou dus altijd niets opleveren.
            return self._met_discriminator(
                {
                    "overall_score": overall,
                    "is_acceptable": bool(is_acceptable),
                    "violations": ensure_list(schema.get("violations", [])),
                    "passed_rules": ensure_list(schema.get("passed_rules", [])),
                },
                result,
            )
        except (ImportError, TypeError, ValueError, AttributeError) as e:
            # DEF-229: Log schema compliance failures for debugging
            logger.debug(
                f"Schema compliance check failed, using attribute fallback: {e}"
            )

        # Final fallback: attribute extraction
        violations = self._extract_violations(result)
        overall_score = self._extract_score(result)
        is_acceptable = self._extract_is_acceptable(result, overall_score)
        passed_rules: list = []
        if hasattr(result, "passed_rules"):
            passed_rules = getattr(result, "passed_rules", [])

        return self._met_discriminator(
            {
                "overall_score": overall_score,
                "is_acceptable": is_acceptable,
                "violations": violations,
                "passed_rules": passed_rules,
            },
            result,
        )

    def _handle_regeneration_context(self, begrip: str, kwargs: dict) -> str:
        """Handle regeneration context enhancement if present (deprecated - always returns base instructions)."""
        return cast(str, ensure_string(safe_dict_get(kwargs, "extra_instructies", "")))

    def _build_ui_metadata(self, response: Any) -> dict[str, Any]:
        """Bouw het metadata-deel van de UI-response (incl. geselecteerde web-lookup-velden)."""
        metadata: dict[str, Any] = {}
        if not (response.definition and response.definition.metadata):
            return metadata
        md = response.definition.metadata
        metadata = {
            "prompt_template": safe_dict_get(md, "prompt_template"),
            "prompt_text": safe_dict_get(md, "prompt_text"),
            "context": ensure_dict(safe_dict_get(md, "context", {})),
            "generation_id": ensure_string(safe_dict_get(md, "generation_id", "")),
            "duration": safe_dict_get(md, "processing_time", 0.0),
            "model": ensure_string(safe_dict_get(md, "model", "")),
        }
        for k in (
            "web_lookup_status",
            "web_lookup_available",
            "web_lookup_timeout",
            "web_sources_count",
            "web_lookup_debug",
            "web_lookup_debug_available",
            # DEF-622 (besluit tekstvergelijking): de echte tekststadia voor
            # de gedeelde renderer; alleen doorgeven wat de generatie leverde.
            "definitie_kern_geextraheerd",
            "definitie_eindtekst",
            "tekst_na_generatie_aangepast",
        ):
            v = safe_dict_get(md, k)
            if v is not None:
                metadata[k] = v
        return metadata

    def to_ui_response(self, response: Any) -> "UIResponseDict":
        """Convert orchestrator response to canonical UI format.

        Dit is de enige serialisatie-seam tussen het getypeerde orchestrator-response
        en de canonieke UI-dict (DEF-451): bevat de failure-afhandeling en de legacy
        compat-aliassen die voorheen in ``generate_definition`` stonden.
        Creates a UIResponseDict with all required fields populated.
        No best iteration attr, no is_valid, only the canonical V2 format.
        """

        # Failure-pad: voorheen vóór de to_ui_response-aanroep in generate_definition.
        # Directe attribute-access (response is altijd DefinitionResponse(V2), beide
        # hebben success/definition) — matcht het oude generate_definition-gedrag en
        # maskeert geen type-fouten (review-MEDIUM #283).
        if not response.success or not response.definition:
            failure = self._create_failure_response(response)
            # DEF-751 stap 2: een door het model gemeld betekenisconflict is een
            # specifieke non-success: geen definitie ("" i.p.v. de generieke
            # placeholder), geen oordeel, de melding onder één additieve sleutel.
            # Alleen uit de orchestrator-metadata, nooit uit vrije kwargs.
            conflict = self._betekenisconflict_uit(response)
            if conflict is not None:
                failure["betekenisconflict"] = conflict
                failure["definitie_origineel"] = ""
                failure["definitie_gecorrigeerd"] = ""
            return failure

        # Extract definition text
        definitie_text = ""
        definitie_origineel = ""
        if response.success and response.definition:
            definitie_text = response.definition.definitie
            definitie_origineel = (
                safe_dict_get(response.definition.metadata, "definitie_origineel")
                or safe_dict_get(response.definition.metadata, "origineel")
                or definitie_text
            )

        # Normalize validation (handle both validation_result and validation)
        validation_data = getattr(response, "validation_result", None) or getattr(
            response, "validation", None
        )
        validation_details = self.normalize_validation(validation_data)

        # Extract voorbeelden from metadata - direct pass-through van canonieke keys
        # REFACTORED: Geen mapping meer nodig, producers leveren al canonieke keys
        voorbeelden = {}
        if response.definition and response.definition.metadata:
            voorbeelden = ensure_dict(
                safe_dict_get(response.definition.metadata, "voorbeelden", {})
            )
            # Direct pass-through - orchestrator heeft al canonieke voorbeelden

            # Debug logging point B - ServiceFactory adapter
            if os.getenv("DEBUG_EXAMPLES"):
                logger.info(
                    "[EXAMPLES-B] Adapter | gen_id=%s | metadata.voorbeelden=%s | ui_keys=%s",
                    safe_dict_get(response.definition.metadata, "generation_id"),
                    (
                        "present"
                        if safe_dict_get(response.definition.metadata, "voorbeelden")
                        else "missing"
                    ),
                    (
                        list((voorbeelden or {}).keys())
                        if isinstance(voorbeelden, dict)
                        else "NOT_DICT"
                    ),
                )

        # Build metadata (include selected web lookup fields for UI status/debugging)
        metadata = self._build_ui_metadata(response)

